    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0x86C0DF577D33488DULL + 0xDFE1345087342315ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xEC231CCB94583E13ULL + 0x818DEF286929FE46ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0xFC628E1BE4D120EDULL + 0x87DFCF4E108A41DAULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xDB0BA766C36C6861ULL + 0xAC736932962D98DCULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xB9F8F6B1E7C6298DULL + 0xB62189C066890B04ULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0x9DB9AEE28697AC63ULL + 0x8088DCE17D2CC471ULL);
