    const std::uint64_t aNonceWordJ = TwistMix64::DiffuseC(pNonce * 0x8E51A73C99940975ULL + 0xF2A30DF401BC4BD2ULL);
    const std::uint64_t aNonceWordK = TwistMix64::DiffuseB(pNonce * 0xFB81C2340EE02933ULL + 0xF1654E5DDA91D788ULL);
    const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0xCD8813F07D498999ULL + 0xC7B46E69E274B43EULL);
    const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0x9148F26A34E51673ULL + 0xCE6BC45394750221ULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseC(pNonce * 0xB4BF2461EACC15E1ULL + 0x9A729F110BEAB74EULL);
