            aOrbiterC = (((aWandererI + RotL64(aCross, 51U)) + RotL64(aCarry, 27U)) + 0x231C06DDB13BFB30ULL) + aNonceWordN;
            aOrbiterA = (aWandererH + RotL64(aIngress, 39U)) + 0x2E5142DC43092155ULL;
            aOrbiterK = (aWandererG + RotL64(aScatter, 46U)) + 0xF9CF94FC702282C3ULL;
            aOrbiterH = (aWandererK + RotL64(aPrevious, 13U)) + 0xE2981A4E915125E4ULL;
            aOrbiterF = (((aWandererD + RotL64(aCross, 21U)) + RotL64(aCarry, 13U)) + 0x092B10E33BF3B62DULL) + aOASaltG[(((511U - aIndex) + 159U)) & S_SALT1];
            aOrbiterG = (aWandererB + RotL64(aIngress, 41U)) + 0x6CDC51DFBC8AA4F2ULL;
            aOrbiterB = ((aWandererJ + RotL64(aScatter, 11U)) + 0x61E0239EC23F65B8ULL) + aNonceWordD;
            aOrbiterE = (((aWandererF + RotL64(aPrevious, 23U)) + 0x926F0D8B7AEE2A8BULL) + aOASaltB[(((511U - aIndex) + 32U)) & S_SALT1]) + aNonceWordB;
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0xA6467C38326E5BD1ULL;
