            aOrbiterK = RotL64((aOrbiterK * 0x02FD3D430E572981ULL), 39U);
            //
            aOrbiterH = (((aOrbiterH + aOrbiterF) + 0xD34D6E3C13DD34DAULL) + aOUSaltH[((aIndex + 331U)) & S_SALT1]) + aNonceWordJ;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x94A5A2AD1A726F8EULL;
