    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xD4D036E8B36DB92FULL + 0xBE5CCD7AF728A6E2ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xFB21187A5AE494A7ULL + 0xB26F743C642D7EE3ULL);
