    const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xDDD8A550CE262671ULL + 0x8E7D564D7E896DFEULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xCFA38B7D8DD0CC4DULL + 0xB783B1FED24E1943ULL);
