    const std::uint64_t aNonceWordM = TwistMix64::DiffuseB(pNonce * 0xE973F440092D7C61ULL + 0x9AD798954D8D9DFCULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseC(pNonce * 0xB254566095A88F7BULL + 0x9A714668FF83EB90ULL);
