            aCross = (RotL64(aKineticLaneC[((S_BLOCK1 - aIndex + 3833U)) & S_BLOCK1], 12U) ^ RotL64(aKineticLaneA[((S_BLOCK1 - aIndex + 7278U)) & S_BLOCK1], 53U));
            aCross ^= (RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 5277U)) & S_BLOCK1], 35U) ^ RotL64(aVaporLaneB[((S_BLOCK1 - aIndex + 5527U)) & S_BLOCK1], 3U));
