            aWandererD = aWandererD ^ ((((RotL64(aCross, 37U) + aOrbiterB) + RotL64(aOrbiterG, 35U)) + aNonceWordB) + aWUSaltH[((aIndex + 35U)) & S_SALT1]);
            aWandererB = aWandererB + ((((RotL64(aIngress, 10U) + RotL64(aOrbiterG, 38U)) + aOrbiterJ) + aNonceWordA) + aWUSaltB[((aIndex + 228U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererF, 4U));
