    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xC644B11B9FD19AE9ULL + 0x9AEF4FC8C0E61977ULL);
