            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0x6725C4C3BB599B4BULL) ^ aOUSaltC[((aIndex + 80U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x2A3A37E98E95288DULL), 11U);
