            aIngress = aIngress + (RotL64(aOrbiterG, 37U) ^ aOrbiterD);
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterJ, 13U));
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterI, 34U));
            aIngress = aIngress + RotL64(aOrbiterF, 27U);
