            aWandererJ = aWandererJ ^ ((((RotL64(aPrevious, 11U) + RotL64(aOrbiterF, 19U)) + aOrbiterC) + RotL64(aCarry, 21U)) + aWUSaltD[(((511U - aIndex) + 25U)) & S_SALT1]);
