            aWandererK = aWandererK ^ ((RotL64(aIngress, 53U) + aOrbiterJ) + RotL64(aOrbiterH, 57U));
            aWandererD = aWandererD + ((RotL64(aScatter, 46U) + RotL64(aOrbiterC, 13U)) + aOrbiterK);
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 41U) + RotL64(aOrbiterB, 27U)) + aOrbiterE) + aWUSaltF[(((511U - aIndex) + 469U)) & S_SALT1]);
            aWandererB = aWandererB + ((((RotL64(aCross, 3U) + RotL64(aOrbiterE, 3U)) + aOrbiterA) + RotL64(aCarry, 5U)) + aWUSaltE[((aIndex + 264U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aIngress, 29U) + RotL64(aOrbiterD, 48U)) + aOrbiterF) + aWUSaltA[((aIndex + 478U)) & S_SALT1]);
            aWandererA = aWandererA + ((RotL64(aScatter, 34U) + RotL64(aOrbiterH, 29U)) + aOrbiterI);
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 13U) + RotL64(aOrbiterG, 53U)) + aOrbiterJ);
            //
            aCarry = aCarry + (RotL64(aWandererC, 27U) ^ aWandererJ);
