            aOrbiterI = (aWandererC + RotL64(aScatter, 21U)) + 0x2F8E6880A6FEA149ULL;
            aOrbiterH = ((aWandererA + RotL64(aPrevious, 34U)) + RotL64(aCarry, 13U)) + 0x23B92AF9417680CBULL;
            aOrbiterF = (aWandererK + RotL64(aCross, 39U)) + 0x7C54526CC09D30A5ULL;
            aOrbiterG = ((aWandererE + RotL64(aIngress, 23U)) + 0x9E32A44EBB33576AULL) + aOASaltC[((aIndex + 50U)) & S_SALT1];
