            aOrbiterJ = (((aWandererB + RotL64(aPrevious, 47U)) + RotL64(aCarry, 51U)) + 0xC80865DD69AD15FCULL) + aOASaltG[(((511U - aIndex) + 391U)) & S_SALT1];
            aOrbiterK = ((aWandererJ + RotL64(aCross, 53U)) + 0x7B9EDD7477BA7DC2ULL) + aOASaltB[((aIndex + 302U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aIngress, 5U)) + 0x5DB27CAD37F24549ULL) + aOASaltH[((aIndex + 331U)) & S_SALT1];
            aOrbiterE = ((aWandererD + RotL64(aScatter, 37U)) + RotL64(aCarry, 39U)) + 0x1BEFACEA74761754ULL;
            aOrbiterD = (aWandererI + RotL64(aPrevious, 26U)) + 0xF1AB27E657CF09A7ULL;
