            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0xE7B5477AD65C5524ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xD685D1E952194B89ULL), 23U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x92854E82670F872BULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0xC0CB1A21F13D0755ULL) ^ aOUSaltB[(((511U - aIndex) + 297U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x2F517A372597C9BBULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x8E28DB6263E03820ULL;
