            aWandererC = aWandererC ^ ((RotL64(aPrevious, 37U) + aOrbiterF) + RotL64(aOrbiterK, 51U));
            aWandererD = aWandererD + ((RotL64(aCross, 14U) + aOrbiterJ) + RotL64(aOrbiterA, 19U));
            aWandererF = aWandererF ^ (((RotL64(aIngress, 53U) + aOrbiterI) + RotL64(aOrbiterD, 21U)) + aWUSaltG[(((511U - aIndex) + 342U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aScatter, 21U) + RotL64(aOrbiterG, 35U)) + aOrbiterI);
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 51U) + RotL64(aOrbiterE, 48U)) + aOrbiterG) + RotL64(aCarry, 3U));
            aWandererB = aWandererB + ((RotL64(aCross, 29U) + RotL64(aOrbiterK, 29U)) + aOrbiterB);
            aWandererA = aWandererA ^ ((RotL64(aIngress, 23U) + RotL64(aOrbiterD, 39U)) + aOrbiterF);
            aWandererI = aWandererI + ((RotL64(aScatter, 60U) + aOrbiterC) + RotL64(aOrbiterJ, 27U));
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 35U) + aOrbiterA) + RotL64(aOrbiterH, 53U)) + aWUSaltD[(((511U - aIndex) + 31U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aCross, 3U) + aOrbiterB) + RotL64(aOrbiterC, 41U)) + RotL64(aCarry, 41U));
            //
            aCarry = aCarry + (RotL64(aWandererJ, 21U) ^ aWandererC);
