            //
            aOrbiterB = ((aWandererK + RotL64(aIngress, 13U)) + 0xC2292EAC5F901C9FULL) + aOASaltB[((aIndex + 321U)) & S_SALT1];
            aOrbiterC = (((aWandererA + RotL64(aScatter, 50U)) + RotL64(aCarry, 57U)) + 0x394FD75F07F1AD06ULL) + aOASaltC[((aIndex + 54U)) & S_SALT1];
