            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0xB5D486FBF6352268ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xA356AC5BA7D89A39ULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xFAFCD14C94316792ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0xD91352DC9E6872A8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x88D016D7578667B5ULL), 39U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x17E134B8B7A109EAULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xA336C828C5DF343BULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x672FD5CB42444E97ULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0xD8485808F0336D69ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x0D5AAA67A1A10478ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x9A14645B9DFDC9E7ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x381F647793016676ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x8372549F92F17098ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x33D78547F7C10603ULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xF912FA85AF44897BULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterJ) ^ 0x6562AA2BF4481B1EULL) ^ aOUSaltA[((aIndex + 118U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x44BA440C2C80ED9BULL), 27U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x786845C21E125B3CULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0xDDE1E5CC61ED683EULL;
            aOrbiterD = RotL64((aOrbiterD * 0x8C0827B0E8D5AB45ULL), 53U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0xEDA48285EC4E0482ULL) + aOUSaltH[((aIndex + 395U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x49242A91F945A0F5ULL;
