            aWandererH = aWandererH ^ (((RotL64(aIngress, 39U) + aOrbiterB) + RotL64(aOrbiterC, 57U)) + RotL64(aCarry, 21U));
            aWandererB = aWandererB + ((RotL64(aScatter, 27U) + aOrbiterA) + RotL64(aOrbiterF, 29U));
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 18U) + RotL64(aOrbiterD, 18U)) + aOrbiterJ);
            aWandererD = aWandererD + (((RotL64(aCross, 23U) + RotL64(aOrbiterH, 39U)) + aOrbiterE) + aWUSaltB[(((511U - aIndex) + 74U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aIngress, 3U) + RotL64(aOrbiterJ, 13U)) + aOrbiterB);
            //
            aCarry = aCarry + (RotL64(aWandererD, 6U) ^ aWandererB);
            aCarry = aCarry + (aWandererE ^ RotL64(aWandererH, 43U));
            aCarry = aCarry + (RotL64(aWandererI, 29U) ^ aWandererC);
            aCarry = aCarry + (aWandererF ^ RotL64(aWandererG, 51U));
            aCarry = aCarry + (RotL64(aWandererK, 13U) ^ aWandererJ);
            aCarry = aCarry + RotL64(aWandererA, 41U);
            aCarry = aCarry + RotL64(aIngress, 38U);
            aCarry = TwistMix64::DiffuseA(aCarry);
            //
