            aOrbiterI = (((aWandererE + RotL64(aScatter, 23U)) + RotL64(aCarry, 47U)) + 0xE7E5B92B6F56933AULL) + aOASaltC[(((511U - aIndex) + 27U)) & S_SALT1];
