            aOrbiterD = RotL64((aOrbiterD * 0x4AD5E149C1605B81ULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x1C6ABC2EA7973694ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x093876A56BBD8A65ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x7E6A820F43D3ECE5ULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x85B8688B2F64DAACULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xD6FD454CBEF477DDULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC4CCD5F12BD54891ULL), 13U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0xE12BF22242C2B377ULL) + aOUSaltD[((aIndex + 211U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x7C7B5E783C6C2709ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x6368BE0961725427ULL), 53U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x597223DF7E1E854DULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x5EFCCD011A1B87D8ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xE08EDD5E1CF6DDBDULL), 35U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0xDED8B94373A966B7ULL) + aOUSaltA[((aIndex + 255U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xF9A65351B3B64E65ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xBCB32126961C5ED3ULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x51CE818E883E59EBULL;
