            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 16313U)) & S_BLOCK1], 35U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 8974U)) & S_BLOCK1], 43U));
            aCross ^= (RotL64(aMagmaLaneC[((S_BLOCK1 - aIndex + 12059U)) & S_BLOCK1], 10U) ^ RotL64(aCrystalLaneD[((S_BLOCK1 - aIndex + 11130U)) & S_BLOCK1], 19U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 11U) ^ RotL64(aCarry, 51U)) ^ (RotL64(aCross, 23U) + RotL64(aIngress, 38U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterD = ((aWandererD + RotL64(aScatter, 58U)) + 0x0D9E26BC0718A3F5ULL) + aOASaltC[((aIndex + 422U)) & S_SALT1];
