            aOrbiterH = (((aWandererD + RotL64(aPrevious, 53U)) + RotL64(aCarry, 11U)) + 0xFC6AEF7E876634ADULL) + aOASaltH[(((511U - aIndex) + 164U)) & S_SALT1];
