            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x37E380A68ACFE65CULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0xF0C77B38DC5BBE20ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x3E9FBDF3983F4545ULL), 29U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x8E4AED4FD631CCBFULL;
