            aWandererG = aWandererG ^ (((RotL64(aCross, 37U) + aOrbiterI) + RotL64(aOrbiterE, 23U)) + aWUSaltF[(((511U - aIndex) + 511U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aIngress, 23U) + aOrbiterG) + RotL64(aOrbiterK, 35U));
            aWandererB = aWandererB ^ (((RotL64(aScatter, 6U) + aOrbiterC) + RotL64(aOrbiterI, 60U)) + aWUSaltD[(((511U - aIndex) + 299U)) & S_SALT1]);
            aWandererK = aWandererK + ((((RotL64(aPrevious, 11U) + RotL64(aOrbiterJ, 29U)) + aOrbiterC) + RotL64(aCarry, 57U)) + aWUSaltG[((aIndex + 349U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererJ, 3U) ^ aWandererI);
