            aOrbiterB = ((aWandererE + RotL64(aIngress, 13U)) + RotL64(aCarry, 13U)) + 0x1075AEC3A20E3CF0ULL;
            aOrbiterJ = (aWandererH + RotL64(aScatter, 21U)) + 0x953DC956DCF38F13ULL;
            aOrbiterE = ((aWandererJ + RotL64(aPrevious, 41U)) + 0x7C42B9B7685C4C52ULL) + aOASaltC[(((511U - aIndex) + 15U)) & S_SALT1];
