            aOrbiterG = ((aWandererK + RotL64(aIngress, 48U)) + RotL64(aCarry, 23U)) + 0x24853BDA582F4F6FULL;
            aOrbiterF = ((aWandererG + RotL64(aScatter, 11U)) + 0xE7A2917A7030B934ULL) + aOASaltF[((aIndex + 284U)) & S_SALT1];
